SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2021.Year, Станции2021.NUST, Станции2021.nr, Станции2021.E, Станции2021.EOTP, Станции2021.EUST*0.029288 AS EUST_TDj, Станции2021.Q, Станции2021.TUST*0.029288 AS TUST_TDj, Станции2021.B * 0.029288 AS B_TDj, Станции2021.GAZ * 0.029288 AS GAZ_TDj, Станции2021.ISK_GAZ * 0.029288 AS ISK_GAZ_TDj, Доп_угли2021.gaz_prir * 0.029288 AS gaz_prir_TDj, Доп_угли2021.gazpp * 0.029288 AS gazpp_TDj, Станции2021.MAZUT * 0.029288 AS MAZUT_TDj, Доп_угли2021.maztop * 0.029288 AS maztop_TDj, Доп_угли2021.nft_proch * 0.029288 AS nft_proch_TDj, Доп_угли2021.disel * 0.029288 AS disel_TDj, Станции2021.TORF * 0.029288 AS TORF_TDj, Станции2021.SLAN * 0.029288 AS SLAN_TDj, Станции2021.PROCH * 0.029288 AS PROCH_TDj, Доп_угли2021.domen_g * 0.029288 AS domen_g_TDj, Доп_угли2021.koks_g * 0.029288 AS koks_g_TDj, Доп_угли2021.prochgaz * 0.029288 AS prochgaz_TDj, Доп_угли2021.tvproch * 0.029288 AS tvproch_TDj, Доп_угли2021.szh_gaz * 0.029288 AS szh_gaz_TDj, Доп_угли2021.inoe * 0.029288 AS inoe_TDj, Станции2021.UGOL * 0.029288 AS UGOL_TDj, Станции2021.DON * 0.029288 AS DON_TDj, Станции2021.PODM * 0.029288 AS PODM_TDj, Станции2021.PECH * 0.029288 AS PECH_TDj, Доп_угли2021.intin * 0.029288 AS intin_TDj, Доп_угли2021.vork * 0.029288 AS vork_TDj, Станции2021.ARKT * 0.029288 AS ARKT_TDj, Станции2021.KUZN * 0.029288 AS KUZN_TDj, Доп_угли2021.kuzngd * 0.029288 AS kuzngd_TDj, Доп_угли2021.kuznt * 0.029288 AS kuznt_TDj, Доп_угли2021.kuznss * 0.029288 AS kuznss_TDj, Доп_угли2021.kuznun * 0.029288 AS kuznun_TDj, Станции2021.URAL * 0.029288 AS URAL_TDj, Доп_угли2021.sver * 0.029288 AS sver_TDj, Доп_угли2021.chel * 0.029288 AS chel_TDj, Доп_угли2021.kizel * 0.029288 AS kizel_TDj, Станции2021.BASHK * 0.029288 AS BASHK_TDj, Станции2021.KAN * 0.029288 AS KAN_TDj, Доп_угли2021.nazar * 0.029288 AS nazar_TDj, Доп_угли2021.ibor * 0.029288 AS ibor_TDj, Доп_угли2021.berez * 0.029288 AS berez_TDj, Доп_угли2021.per * 0.029288 AS per_TDj, Доп_угли2021.irbei * 0.029288 AS irbei_TDj, Доп_угли2021.kansk * 0.029288 AS kansk_TDj, Станции2021.TUNG * 0.029288 AS TUNG_TDj, Доп_угли2021.jer * 0.029288 AS jer_TDj, Доп_угли2021.karab * 0.029288 AS karab_TDj, Станции2021.IRKUT * 0.029288 AS IRKUT_TDj, Доп_угли2021.azey * 0.029288 AS azey_TDj, Доп_угли2021.mug * 0.029288 AS mug_TDj, Доп_угли2021.cher * 0.029288 AS cher_TDj, Станции2021.HAK * 0.029288 AS HAK_TDj, Станции2021.TUV * 0.029288 AS TUV_TDj, Станции2021.BUR * 0.029288 AS BUR_TDj, Доп_угли2021.gusin * 0.029288 AS gusin_TDj, Доп_угли2021.tugn * 0.029288 AS tugn_TDj, Доп_угли2021.okino * 0.029288 AS okino_TDj, Станции2021.CHIT * 0.029288 AS CHIT_TDj, Доп_угли2021.har * 0.029288 AS har_TDj, Доп_угли2021.urt * 0.029288 AS urt_TDj, Доп_угли2021.tataur * 0.029288 AS tataur_TDj, Доп_угли2021.tarbag * 0.029288 AS tarbag_TDj, Доп_угли2021.zab_kam * 0.029288 AS zab_kam_TDj, Станции2021.YAKUT * 0.029288 AS YAKUT_TDj, Доп_угли2021.neru * 0.029288 AS neru_TDj, Доп_угли2021.zyryan * 0.029288 AS zyryan_TDj, Доп_угли2021.pyak * 0.029288 AS pyak_TDj, Станции2021.AMUR * 0.029288 AS AMUR_TDj, Доп_угли2021.rai * 0.029288 AS rai_TDj, Доп_угли2021.erk * 0.029288 AS erk_TDj, Доп_угли2021.ogodj * 0.029288 AS ogodj_TDj, Станции2021.URG * 0.029288 AS URG_TDj, Станции2021.USHUM * 0.029288 AS USHUM_TDj, Станции2021.PRIM * 0.029288 AS PRIM_TDj, Доп_угли2021.bikin * 0.029288 AS bikin_TDj, Доп_угли2021.razdol * 0.029288 AS razdol_TDj, Доп_угли2021.hankai * 0.029288 AS hankai_TDj, Станции2021.MAG * 0.029288 AS MAG_TDj, Станции2021.SAH * 0.029288 AS SAH_TDj, Станции2021.KAMCH * 0.029288 AS KAMCH_TDj, Станции2021.CHUKOT * 0.029288 AS CHUKOT_TDj, Доп_угли2021.anad * 0.029288 AS anad_TDj, Доп_угли2021.bering * 0.029288 AS bering_TDj, Станции2021.KAZAH * 0.029288 AS KAZAH_TDj, Доп_угли2021.ekib * 0.029288 AS ekib_TDj, Доп_угли2021.maikub * 0.029288 AS maikub_TDj, Доп_угли2021.karag * 0.029288 AS karag_TDj, Доп_угли2021.karajyra * 0.029288 AS karajyra_TDj, Доп_угли2021.teniz * 0.029288 AS teniz_TDj, Станции2021.QOTR, Станции2021.SNK, Станции2021.EWTP, Станции2021.NT, Станции2021.OBOR, Станции2021.VED, Станции2021.OBL, Станции2021.DEP, Станции2021.OES, Станции2021.ER, Станции2021.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, имена_БЕ.name AS namebe, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет",IIf([obor]=24,"ГПА","ПСУ"))))) AS тип, Станции2021.SNt, Имена_станций.n1 AS [мощность блока], IIf([B]>0,[gaz]/[B]*100,0) AS dolya_gaz, IIf([B]>0,[ugol]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[mazut]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[torf]/[B]*100,0) AS dolya_torf, IIf([B]>0,[slan]/[B]*100,0) AS dolya_slan, IIf([B]>0,[proch]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf(([dolya_gaz]+[dolya_domen_g]+[dolya_koks_g]+[dolya_prochgaz])>=50,"gaz",IIf([dolya_ugol]>=50,"ugol","prochee")) AS Belyaev, IIf([Имена_станций].[BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Имена_станций].[Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([Станции2021].[вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved, [EUST]/[B] AS [dolya topl na ee], [TUST]/[B] AS [dolya topl na q], Удельные2021.BK, Удельные2021.BTP, Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([E]>0,[E]/[NUST]*1000,0) AS H_ust
FROM Удельные2021 RIGHT JOIN ((((Имена_станций INNER JOIN (Имена_областей RIGHT JOIN (Имена_ОЭС INNER JOIN (Станции2021 LEFT JOIN Доп_угли2021 ON (Станции2021.NUMB1120 = Доп_угли2021.NUMB1120) AND (Станции2021.YEAR = Доп_угли2021.YEAR)) ON Имена_ОЭС.oes = Станции2021.OES) ON Имена_областей.OBL = Станции2021.OBL) ON Имена_станций.NUMB = Станции2021.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) LEFT JOIN имена_БЕ ON Имена_станций.BE = имена_БЕ.code) INNER JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code) ON Удельные2021.NUMB1120 = Станции2021.NUMB1120;
